            pd3_rrr(3, 1, 1) = pd3_rrr(3, 1, 1) + t_pd3_rrr_002
            t_pd3_rrr_011 = d_a(1)*x39 - d_a(1)*x40 + d_a(1)*x41 + x42
            pd3_rrr(1, 2, 2) = pd3_rrr(1, 2, 2) + t_pd3_rrr_011
            pd3_rrr(2, 1, 2) = pd3_rrr(2, 1, 2) + t_pd3_rrr_011
            pd3_rrr(2, 2, 1) = pd3_rrr(2, 2, 1) + t_pd3_rrr_011
            t_pd3_rrr_012 = d_a(1)*x46 + d_a(3)*x44 - d_a(3)*x47
            pd3_rrr(1, 2, 3) = pd3_rrr(1, 2, 3) + t_pd3_rrr_012
            pd3_rrr(1, 3, 2) = pd3_rrr(1, 3, 2) + t_pd3_rrr_012
            pd3_rrr(2, 1, 3) = pd3_rrr(2, 1, 3) + t_pd3_rrr_012
            pd3_rrr(2, 3, 1) = pd3_rrr(2, 3, 1) + t_pd3_rrr_012
            pd3_rrr(3, 1, 2) = pd3_rrr(3, 1, 2) + t_pd3_rrr_012
            pd3_rrr(3, 2, 1) = pd3_rrr(3, 2, 1) + t_pd3_rrr_012
            t_pd3_rrr_022 = d_a(1)*x48 - d_a(1)*x49 + d_a(1)*x50 + x42
            pd3_rrr(1, 3, 3) = pd3_rrr(1, 3, 3) + t_pd3_rrr_022
            pd3_rrr(3, 1, 3) = pd3_rrr(3, 1, 3) + t_pd3_rrr_022
            pd3_rrr(3, 3, 1) = pd3_rrr(3, 3, 1) + t_pd3_rrr_022
            pd3_rrr(2, 2, 2) = &
               pd3_rrr(2, 2, 2) + (-3.0_wp*x16 + x23*x52 - x28*x52 + x29*x51 + 3.0_wp*x35)
            t_pd3_rrr_112 = d_a(3)*x39 - d_a(3)*x40 + d_a(3)*x41 + x38
            pd3_rrr(2, 2, 3) = pd3_rrr(2, 2, 3) + t_pd3_rrr_112
            pd3_rrr(2, 3, 2) = pd3_rrr(2, 3, 2) + t_pd3_rrr_112
            pd3_rrr(3, 2, 2) = pd3_rrr(3, 2, 2) + t_pd3_rrr_112
            t_pd3_rrr_122 = d_a(2)*x48 - d_a(2)*x49 + d_a(2)*x50 + x36
            pd3_rrr(2, 3, 3) = pd3_rrr(2, 3, 3) + t_pd3_rrr_122
            pd3_rrr(3, 2, 3) = pd3_rrr(3, 2, 3) + t_pd3_rrr_122
            pd3_rrr(3, 3, 2) = pd3_rrr(3, 3, 2) + t_pd3_rrr_122
            pd3_rrr(3, 3, 3) = &
               pd3_rrr(3, 3, 3) + (-3.0_wp*x17 + x23*x54 - x28*x54 + x29*x53 + 3.0_wp*x37)
            pd4_rrrr(1, 1, 1, 1) = &
               pd4_rrrr(1, 1, 1, 1) + (x23*x58 - x28*x58 + 6.0_wp*x30 + x56*x57 - x56*x61 - &
               x59*x60 + x59*x62 + x63)
            t_pd4_rrrr_0001 = d_a(2)*x64 - d_a(2)*x67 - x60*x66 + x62*x66 + x70
            pd4_rrrr(1, 1, 1, 2) = pd4_rrrr(1, 1, 1, 2) + t_pd4_rrrr_0001
            pd4_rrrr(1, 1, 2, 1) = pd4_rrrr(1, 1, 2, 1) + t_pd4_rrrr_0001
            pd4_rrrr(1, 2, 1, 1) = pd4_rrrr(1, 2, 1, 1) + t_pd4_rrrr_0001
            pd4_rrrr(2, 1, 1, 1) = pd4_rrrr(2, 1, 1, 1) + t_pd4_rrrr_0001
            t_pd4_rrrr_0002 = d_a(3)*x64 - d_a(3)*x67 - x60*x71 + x62*x71 + x75
            pd4_rrrr(1, 1, 1, 3) = pd4_rrrr(1, 1, 1, 3) + t_pd4_rrrr_0002
            pd4_rrrr(1, 1, 3, 1) = pd4_rrrr(1, 1, 3, 1) + t_pd4_rrrr_0002
            pd4_rrrr(1, 3, 1, 1) = pd4_rrrr(1, 3, 1, 1) + t_pd4_rrrr_0002
            pd4_rrrr(3, 1, 1, 1) = pd4_rrrr(3, 1, 1, 1) + t_pd4_rrrr_0002
            t_pd4_rrrr_0011 = x2*x77 - x78*x79 - x78*x80 + x78*x81 + x83 + x84
            pd4_rrrr(1, 1, 2, 2) = pd4_rrrr(1, 1, 2, 2) + t_pd4_rrrr_0011
            pd4_rrrr(1, 2, 1, 2) = pd4_rrrr(1, 2, 1, 2) + t_pd4_rrrr_0011
            pd4_rrrr(1, 2, 2, 1) = pd4_rrrr(1, 2, 2, 1) + t_pd4_rrrr_0011
            pd4_rrrr(2, 1, 1, 2) = pd4_rrrr(2, 1, 1, 2) + t_pd4_rrrr_0011
            pd4_rrrr(2, 1, 2, 1) = pd4_rrrr(2, 1, 2, 1) + t_pd4_rrrr_0011
            pd4_rrrr(2, 2, 1, 1) = pd4_rrrr(2, 2, 1, 1) + t_pd4_rrrr_0011
            t_pd4_rrrr_0012 = -x31*x85 + x33*x85 + x46 + x77*x85 - x79*x86 - x80*x86 + x81*x86
            pd4_rrrr(1, 1, 2, 3) = pd4_rrrr(1, 1, 2, 3) + t_pd4_rrrr_0012
            pd4_rrrr(1, 1, 3, 2) = pd4_rrrr(1, 1, 3, 2) + t_pd4_rrrr_0012
            pd4_rrrr(1, 2, 1, 3) = pd4_rrrr(1, 2, 1, 3) + t_pd4_rrrr_0012
            pd4_rrrr(1, 2, 3, 1) = pd4_rrrr(1, 2, 3, 1) + t_pd4_rrrr_0012
            pd4_rrrr(1, 3, 1, 2) = pd4_rrrr(1, 3, 1, 2) + t_pd4_rrrr_0012
            pd4_rrrr(1, 3, 2, 1) = pd4_rrrr(1, 3, 2, 1) + t_pd4_rrrr_0012
            pd4_rrrr(2, 1, 1, 3) = pd4_rrrr(2, 1, 1, 3) + t_pd4_rrrr_0012
            pd4_rrrr(2, 1, 3, 1) = pd4_rrrr(2, 1, 3, 1) + t_pd4_rrrr_0012
            pd4_rrrr(2, 3, 1, 1) = pd4_rrrr(2, 3, 1, 1) + t_pd4_rrrr_0012
            pd4_rrrr(3, 1, 1, 2) = pd4_rrrr(3, 1, 1, 2) + t_pd4_rrrr_0012
            pd4_rrrr(3, 1, 2, 1) = pd4_rrrr(3, 1, 2, 1) + t_pd4_rrrr_0012
            pd4_rrrr(3, 2, 1, 1) = pd4_rrrr(3, 2, 1, 1) + t_pd4_rrrr_0012
            t_pd4_rrrr_0022 = x3*x77 - x79*x87 - x80*x87 + x81*x87 + x83 + x88
            pd4_rrrr(1, 1, 3, 3) = pd4_rrrr(1, 1, 3, 3) + t_pd4_rrrr_0022
            pd4_rrrr(1, 3, 1, 3) = pd4_rrrr(1, 3, 1, 3) + t_pd4_rrrr_0022
            pd4_rrrr(1, 3, 3, 1) = pd4_rrrr(1, 3, 3, 1) + t_pd4_rrrr_0022
            pd4_rrrr(3, 1, 1, 3) = pd4_rrrr(3, 1, 1, 3) + t_pd4_rrrr_0022
            pd4_rrrr(3, 1, 3, 1) = pd4_rrrr(3, 1, 3, 1) + t_pd4_rrrr_0022
            pd4_rrrr(3, 3, 1, 1) = pd4_rrrr(3, 3, 1, 1) + t_pd4_rrrr_0022
            t_pd4_rrrr_0111 = x51*x89 + x70 - x79*x90 - x80*x90 + x81*x90
            pd4_rrrr(1, 2, 2, 2) = pd4_rrrr(1, 2, 2, 2) + t_pd4_rrrr_0111
            pd4_rrrr(2, 1, 2, 2) = pd4_rrrr(2, 1, 2, 2) + t_pd4_rrrr_0111
            pd4_rrrr(2, 2, 1, 2) = pd4_rrrr(2, 2, 1, 2) + t_pd4_rrrr_0111
            pd4_rrrr(2, 2, 2, 1) = pd4_rrrr(2, 2, 2, 1) + t_pd4_rrrr_0111
            t_pd4_rrrr_0112 = d_a(3)*x2*x89 - x31*x72 + x33*x72 + x74 - x79*x91 - x80*x91 + x81*x91
            pd4_rrrr(1, 2, 2, 3) = pd4_rrrr(1, 2, 2, 3) + t_pd4_rrrr_0112
            pd4_rrrr(1, 2, 3, 2) = pd4_rrrr(1, 2, 3, 2) + t_pd4_rrrr_0112
            pd4_rrrr(1, 3, 2, 2) = pd4_rrrr(1, 3, 2, 2) + t_pd4_rrrr_0112
            pd4_rrrr(2, 1, 2, 3) = pd4_rrrr(2, 1, 2, 3) + t_pd4_rrrr_0112
            pd4_rrrr(2, 1, 3, 2) = pd4_rrrr(2, 1, 3, 2) + t_pd4_rrrr_0112
            pd4_rrrr(2, 2, 1, 3) = pd4_rrrr(2, 2, 1, 3) + t_pd4_rrrr_0112
            pd4_rrrr(2, 2, 3, 1) = pd4_rrrr(2, 2, 3, 1) + t_pd4_rrrr_0112
            pd4_rrrr(2, 3, 1, 2) = pd4_rrrr(2, 3, 1, 2) + t_pd4_rrrr_0112
            pd4_rrrr(2, 3, 2, 1) = pd4_rrrr(2, 3, 2, 1) + t_pd4_rrrr_0112
            pd4_rrrr(3, 1, 2, 2) = pd4_rrrr(3, 1, 2, 2) + t_pd4_rrrr_0112
            pd4_rrrr(3, 2, 1, 2) = pd4_rrrr(3, 2, 1, 2) + t_pd4_rrrr_0112
            pd4_rrrr(3, 2, 2, 1) = pd4_rrrr(3, 2, 2, 1) + t_pd4_rrrr_0112
            t_pd4_rrrr_0122 = d_a(2)*x3*x89 + x44 - x47 + x69 - x79*x92 - x80*x92 + x81*x92
            pd4_rrrr(1, 2, 3, 3) = pd4_rrrr(1, 2, 3, 3) + t_pd4_rrrr_0122
            pd4_rrrr(1, 3, 2, 3) = pd4_rrrr(1, 3, 2, 3) + t_pd4_rrrr_0122
            pd4_rrrr(1, 3, 3, 2) = pd4_rrrr(1, 3, 3, 2) + t_pd4_rrrr_0122
            pd4_rrrr(2, 1, 3, 3) = pd4_rrrr(2, 1, 3, 3) + t_pd4_rrrr_0122
            pd4_rrrr(2, 3, 1, 3) = pd4_rrrr(2, 3, 1, 3) + t_pd4_rrrr_0122
            pd4_rrrr(2, 3, 3, 1) = pd4_rrrr(2, 3, 3, 1) + t_pd4_rrrr_0122
            pd4_rrrr(3, 1, 2, 3) = pd4_rrrr(3, 1, 2, 3) + t_pd4_rrrr_0122
            pd4_rrrr(3, 1, 3, 2) = pd4_rrrr(3, 1, 3, 2) + t_pd4_rrrr_0122
            pd4_rrrr(3, 2, 1, 3) = pd4_rrrr(3, 2, 1, 3) + t_pd4_rrrr_0122
            pd4_rrrr(3, 2, 3, 1) = pd4_rrrr(3, 2, 3, 1) + t_pd4_rrrr_0122
            pd4_rrrr(3, 3, 1, 2) = pd4_rrrr(3, 3, 1, 2) + t_pd4_rrrr_0122
            pd4_rrrr(3, 3, 2, 1) = pd4_rrrr(3, 3, 2, 1) + t_pd4_rrrr_0122
            t_pd4_rrrr_0222 = x53*x89 + x75 - x79*x93 - x80*x93 + x81*x93
            pd4_rrrr(1, 3, 3, 3) = pd4_rrrr(1, 3, 3, 3) + t_pd4_rrrr_0222
            pd4_rrrr(3, 1, 3, 3) = pd4_rrrr(3, 1, 3, 3) + t_pd4_rrrr_0222
            pd4_rrrr(3, 3, 1, 3) = pd4_rrrr(3, 3, 1, 3) + t_pd4_rrrr_0222
            pd4_rrrr(3, 3, 3, 1) = pd4_rrrr(3, 3, 3, 1) + t_pd4_rrrr_0222
            pd4_rrrr(2, 2, 2, 2) = &
               pd4_rrrr(2, 2, 2, 2) + (x23*x95 - x28*x95 + 6.0_wp*x39 - x60*x96 + x62*x96 + x63 + &
               x76*x94 - x80*x94)
            t_pd4_rrrr_1112 = x76*x97 - x79*x97 - x80*x97 + x81*x97 + x99
            pd4_rrrr(2, 2, 2, 3) = pd4_rrrr(2, 2, 2, 3) + t_pd4_rrrr_1112
            pd4_rrrr(2, 2, 3, 2) = pd4_rrrr(2, 2, 3, 2) + t_pd4_rrrr_1112
            pd4_rrrr(2, 3, 2, 2) = pd4_rrrr(2, 3, 2, 2) + t_pd4_rrrr_1112
            pd4_rrrr(3, 2, 2, 2) = pd4_rrrr(3, 2, 2, 2) + t_pd4_rrrr_1112
            t_pd4_rrrr_1122 = x100*x76 - x100*x79 - x100*x80 + x100*x81 + x15 + x82 + x84 + x88
            pd4_rrrr(2, 2, 3, 3) = pd4_rrrr(2, 2, 3, 3) + t_pd4_rrrr_1122
            pd4_rrrr(2, 3, 2, 3) = pd4_rrrr(2, 3, 2, 3) + t_pd4_rrrr_1122
            pd4_rrrr(2, 3, 3, 2) = pd4_rrrr(2, 3, 3, 2) + t_pd4_rrrr_1122
            pd4_rrrr(3, 2, 2, 3) = pd4_rrrr(3, 2, 2, 3) + t_pd4_rrrr_1122
            pd4_rrrr(3, 2, 3, 2) = pd4_rrrr(3, 2, 3, 2) + t_pd4_rrrr_1122
            pd4_rrrr(3, 3, 2, 2) = pd4_rrrr(3, 3, 2, 2) + t_pd4_rrrr_1122
            t_pd4_rrrr_1222 = x101*x76 - x101*x79 - x101*x80 + x101*x81 + x99
            pd4_rrrr(2, 3, 3, 3) = pd4_rrrr(2, 3, 3, 3) + t_pd4_rrrr_1222
            pd4_rrrr(3, 2, 3, 3) = pd4_rrrr(3, 2, 3, 3) + t_pd4_rrrr_1222
            pd4_rrrr(3, 3, 2, 3) = pd4_rrrr(3, 3, 2, 3) + t_pd4_rrrr_1222
            pd4_rrrr(3, 3, 3, 2) = pd4_rrrr(3, 3, 3, 2) + t_pd4_rrrr_1222
            pd4_rrrr(3, 3, 3, 3) = &
               pd4_rrrr(3, 3, 3, 3) + (x102*x76 - x102*x80 + x103*x23 - x103*x28 - x104*x60 + &
               x104*x62 + 6.0_wp*x48 + x63)
         end block
      end select

   end subroutine cfc_atomic_term_eval

   pure module subroutine cfc_pair_term_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                      max_deriv, pd0, pd1_a, pd1_b, pd2_aa, pd2_ab, pd2_bb, &
                                      pd3_aaa, pd3_aab, pd3_abb, pd3_bbb, pd4_aaaa, pd4_aaab, &
                                      pd4_aabb, pd4_abbb, pd4_bbbb)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Maximum derivative order to accumulate (0..4); a larger value is treated as 4
      integer, intent(in) :: max_deriv
      !> Pseudo-density value accumulator
      real(wp), intent(inout) :: pd0
      !> d^1 K / d(d_a)^1 d(d_b)^0 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd1_a(3)
      !> d^1 K / d(d_a)^0 d(d_b)^1 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd1_b(3)
      !> d^2 K / d(d_a)^2 d(d_b)^0 accumulator (symmetric in the first 2 indices)
      real(wp), intent(inout) :: pd2_aa(3, 3)
      !> d^2 K / d(d_a)^1 d(d_b)^1 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd2_ab(3, 3)
      !> d^2 K / d(d_a)^0 d(d_b)^2 accumulator (symmetric in the last 2 indices)
      real(wp), intent(inout) :: pd2_bb(3, 3)
      !> d^3 K / d(d_a)^3 d(d_b)^0 accumulator (symmetric in the first 3 indices)
      real(wp), intent(inout) :: pd3_aaa(3, 3, 3)
      !> d^3 K / d(d_a)^2 d(d_b)^1 accumulator (symmetric in the first 2 indices)
      real(wp), intent(inout) :: pd3_aab(3, 3, 3)
      !> d^3 K / d(d_a)^1 d(d_b)^2 accumulator (symmetric in the last 2 indices)
      real(wp), intent(inout) :: pd3_abb(3, 3, 3)
      !> d^3 K / d(d_a)^0 d(d_b)^3 accumulator (symmetric in the last 3 indices)
      real(wp), intent(inout) :: pd3_bbb(3, 3, 3)
      !> d^4 K / d(d_a)^4 d(d_b)^0 accumulator (symmetric in the first 4 indices)
      real(wp), intent(inout) :: pd4_aaaa(3, 3, 3, 3)
      !> d^4 K / d(d_a)^3 d(d_b)^1 accumulator (symmetric in the first 3 indices)
      real(wp), intent(inout) :: pd4_aaab(3, 3, 3, 3)
      !> d^4 K / d(d_a)^2 d(d_b)^2 accumulator (symmetric within each index group)
      real(wp), intent(inout) :: pd4_aabb(3, 3, 3, 3)
      !> d^4 K / d(d_a)^1 d(d_b)^3 accumulator (symmetric in the last 3 indices)
      real(wp), intent(inout) :: pd4_abbb(3, 3, 3, 3)
      !> d^4 K / d(d_a)^0 d(d_b)^4 accumulator (symmetric in the last 4 indices)
      real(wp), intent(inout) :: pd4_bbbb(3, 3, 3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         call cfc_pair_term_eval_faded(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                       max_deriv, pd0, pd1_a, pd1_b, pd2_aa, pd2_ab, pd2_bb, &
                                       pd3_aaa, pd3_aab, pd3_abb, pd3_bbb, pd4_aaaa, pd4_aaab, &
                                       pd4_aabb, pd4_abbb, pd4_bbbb, sg_a, sg_b)
         return
      end if

      ! Plateau: plain term, w = 1
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            pd0 = &
               pd0 + (c_par*((-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp)*(-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp)*(-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp)*(-x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + &
               1.0_wp))*exp(a2*(x0*sqrt((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))) + &
               x1*sqrt((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))) - 2.0_wp)))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = -x2*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + 1.0_wp
            x4 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x5 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x6 = c_par*exp(a2*(x0*x4 + x1*x5 - 2.0_wp))
            x7 = (x3*x3*x3*x3)*x6
            x8 = 4.0_wp*x2*(x3*x3*x3)*x6
            x9 = a2*x7
            x10 = x0*x9/x4
            x11 = x1*x9/x5
            pd0 = pd0 + (x7)
            pd1_a(1) = pd1_a(1) + (d_a(1)*x10 - d_b(1)*x8)
            pd1_a(2) = pd1_a(2) + (d_a(2)*x10 - d_b(2)*x8)
            pd1_a(3) = pd1_a(3) + (d_a(3)*x10 - d_b(3)*x8)
            pd1_b(1) = pd1_b(1) + (-d_a(1)*x8 + d_b(1)*x11)
            pd1_b(2) = pd1_b(2) + (-d_a(2)*x8 + d_b(2)*x11)
            pd1_b(3) = pd1_b(3) + (-d_a(3)*x8 + d_b(3)*x11)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
